public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    List<Long> A = new ArrayList<>();
    int n = sc.nextInt();
    for (int i = 0; i < n; i++) {
        A.add(sc.nextLong());
    }
    sc.close();

    List<Long> up = new ArrayList<>();
    List<Long> down = new ArrayList<>();

    Long pre = 0L;
    for (int i = 0; i < n; i++) {
        if (A.get(i) > pre) {
            ++pre;
        } else {
            pre = A.get(i);
        }
        up.add(pre);
    }
    pre = 0L;
    for (int i = n - 1; i >= 0; i--) {
        if (A.get(i) > pre) {
            ++pre;
        } else {
            pre = A.get(i);
        }
        down.add(pre);
    }
    long ans = 0L;
    for (int i = 0; i < n; i++) {
        long min = Math.min(up.get(i), down.get(n - i - 1));
        if (ans < min) {
            ans = min;
        }
    }
    System.out.print(ans);
}

